/// <summary>An authored possible history. Its weight is read only once at process scheduling time.</summary>
public sealed class ConsequenceBranchDefinition
{
    private readonly Dictionary<string, ConsequenceStageDefinition> stages;

    public ConsequenceBranchDefinition(string id, int weight, IEnumerable<ConsequenceStageDefinition> stages)
    {
        if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("Consequence branch id must not be empty.", nameof(id));
        if (weight < 1) throw new ArgumentOutOfRangeException(nameof(weight), "Consequence branch weight must be positive.");
        Id = id.Trim();
        Weight = weight;
        this.stages = (stages ?? throw new ArgumentNullException(nameof(stages)))
            .ToDictionary(stage => stage.Id, StringComparer.Ordinal);
        if (this.stages.Count == 0) throw new ArgumentException("A consequence branch needs at least one stage.", nameof(stages));
    }

    public string Id { get; }
    public int Weight { get; }
    public IReadOnlyCollection<ConsequenceStageDefinition> Stages => stages.Values;
    public ConsequenceStageDefinition? FindStage(string stageId) => stages.TryGetValue(stageId, out var stage) ? stage : null;
}

public sealed class ConsequenceDefinition
{
    private readonly Dictionary<string, ConsequenceBranchDefinition> branches;

    public ConsequenceDefinition(string id, IEnumerable<ConsequenceStageDefinition> stages)
        : this(id, new[] { new ConsequenceBranchDefinition("default", 1, stages) })
    {
    }

    public ConsequenceDefinition(string id, IEnumerable<ConsequenceBranchDefinition> branches)
    {
        if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("Consequence id must not be empty.", nameof(id));
        Id = id.Trim();
        this.branches = (branches ?? throw new ArgumentNullException(nameof(branches))).ToDictionary(branch => branch.Id, StringComparer.Ordinal);
        if (this.branches.Count == 0) throw new ArgumentException("A consequence needs at least one branch.", nameof(branches));
    }

    public string Id { get; }
    public IReadOnlyCollection<ConsequenceBranchDefinition> Branches => branches.Values;
    /// <summary>Compatibility view for legacy callers and stage-only authoring.</summary>
    public IReadOnlyCollection<ConsequenceStageDefinition> Stages => branches.TryGetValue("default", out var branch)
        ? branch.Stages
        : branches.Values.SelectMany(item => item.Stages).ToArray();
    public ConsequenceBranchDefinition? FindBranch(string branchId) => branches.TryGetValue(branchId, out var branch) ? branch : null;
    public ConsequenceStageDefinition? FindStage(string branchId, string stageId) => FindBranch(branchId)?.FindStage(stageId);
    public ConsequenceStageDefinition? FindStage(string stageId) => FindBranch("default")?.FindStage(stageId);

    public ConsequenceBranchDefinition SelectBranch(IDeterministicRandomSource random)
    {
        if (random == null) throw new ArgumentNullException(nameof(random));
        var ordered = branches.Values.OrderBy(branch => branch.Id, StringComparer.Ordinal).ToList();
        if (ordered.Count == 1) return ordered[0];
        var total = ordered.Sum(branch => branch.Weight);
        var roll = random.NextInt(total);
        foreach (var branch in ordered)
        {
            if (roll < branch.Weight) return branch;
            roll -= branch.Weight;
        }

        throw new InvalidOperationException("Consequence branch selection did not resolve a branch.");
    }
}

public sealed class FactionReactionRuleDefinition
{
    private readonly HashSet<LocationFactionRelationKind> relationKinds;
    private readonly HashSet<string> requiredActionTags;
    private readonly HashSet<string> requiredFactionValues;
    private readonly HashSet<string> requiredFactionTabooTags;

    public FactionReactionRuleDefinition(
        string id,
        string triggerId,
        IEnumerable<LocationFactionRelationKind> relationKinds,
        FactionAwarenessLevel minimumAwareness,
        string? factionProfileId,
        int? minimumAnger,
        int? maximumTrust,
        int trustDelta,
        int angerDelta,
        int fearDelta,
        string? memoryId,
        string? eventTitle,
        string? eventBody,
        bool revealsFaction,
        int priority = 0,
        IEnumerable<string>? requiredActionTags = null,
        IEnumerable<string>? requiredFactionValues = null,
        IEnumerable<string>? requiredFactionTabooTags = null)
    {
        if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("Reaction rule id must not be empty.", nameof(id));
        if (string.IsNullOrWhiteSpace(triggerId)) throw new ArgumentException("Reaction rule trigger id must not be empty.", nameof(triggerId));
        Id = id.Trim();
        TriggerId = triggerId.Trim();
        this.relationKinds = new HashSet<LocationFactionRelationKind>(relationKinds ?? throw new ArgumentNullException(nameof(relationKinds)));
        if (this.relationKinds.Count == 0) throw new ArgumentException("Reaction rule needs at least one relation kind.", nameof(relationKinds));
        this.requiredActionTags = new HashSet<string>((requiredActionTags ?? Enumerable.Empty<string>())
            .Where(tag => !string.IsNullOrWhiteSpace(tag))
            .Select(tag => tag.Trim()), StringComparer.Ordinal);
        this.requiredFactionValues = NormalizeTags(requiredFactionValues);
        this.requiredFactionTabooTags = NormalizeTags(requiredFactionTabooTags);
        MinimumAwareness = minimumAwareness;
        FactionProfileId = string.IsNullOrWhiteSpace(factionProfileId) ? null : factionProfileId.Trim();
        MinimumAnger = minimumAnger;
        MaximumTrust = maximumTrust;
        TrustDelta = trustDelta;
        AngerDelta = angerDelta;
        FearDelta = fearDelta;
        MemoryId = string.IsNullOrWhiteSpace(memoryId) ? null : memoryId.Trim();
        EventTitle = string.IsNullOrWhiteSpace(eventTitle) ? null : eventTitle.Trim();
        EventBody = string.IsNullOrWhiteSpace(eventBody) ? null : eventBody.Trim();
        RevealsFaction = revealsFaction;
        Priority = priority;
    }

    public string Id { get; }
    public string TriggerId { get; }
    public IReadOnlyCollection<LocationFactionRelationKind> RelationKinds => relationKinds;
    public IReadOnlyCollection<string> RequiredActionTags => requiredActionTags;
    public IReadOnlyCollection<string> RequiredFactionValues => requiredFactionValues;
    public IReadOnlyCollection<string> RequiredFactionTabooTags => requiredFactionTabooTags;
    public FactionAwarenessLevel MinimumAwareness { get; }
    public string? FactionProfileId { get; }
    public int? MinimumAnger { get; }
    public int? MaximumTrust { get; }
    public int TrustDelta { get; }
    public int AngerDelta { get; }
    public int FearDelta { get; }
    public string? MemoryId { get; }
    public string? EventTitle { get; }
    public string? EventBody { get; }
    public bool RevealsFaction { get; }
    public int Priority { get; }

    public bool Matches(
        FactionState faction,
        FactionProfileDefinition? profile,
        LocationFactionRelationState relation,
        FactionAwarenessLevel awareness,
        WorldTriggerState trigger)
    {
        return relationKinds.Contains(relation.Kind)
            && awareness >= MinimumAwareness
            && (FactionProfileId == null || FactionProfileId == faction.ReactionProfileId)
            && (!MinimumAnger.HasValue || faction.Anger >= MinimumAnger.Value)
            && (!MaximumTrust.HasValue || faction.Trust <= MaximumTrust.Value)
            && requiredActionTags.All(tag => trigger.ActionTags.Contains(tag, StringComparer.Ordinal))
            && requiredFactionValues.All(value => profile != null && profile.Values.Contains(value, StringComparer.Ordinal))
            && requiredFactionTabooTags.All(tag => profile != null && profile.TabooActionTags.Contains(tag, StringComparer.Ordinal));
    }

    private static HashSet<string> NormalizeTags(IEnumerable<string>? values)
    {
        return new HashSet<string>((values ?? Enumerable.Empty<string>())
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value.Trim()), StringComparer.Ordinal);
    }
}

public sealed class FactionTerritoryEntryRuleDefinition
{
    private readonly HashSet<string> requiredFactionValues;

    public FactionTerritoryEntryRuleDefinition(
