/// <summary>JSON-authored order constraints for a scout mission category.</summary>
public sealed class ScoutMissionTypeDefinition
{
    private readonly HashSet<ScoutMissionFocus> allowedFocuses;

    public ScoutMissionTypeDefinition(
        string id,
        string label,
        int minDurationDays,
        int maxDurationDays,
        int maxScouts,
        IEnumerable<ScoutMissionFocus> allowedFocuses)
    {
        if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("Scout mission type id must not be empty.", nameof(id));
        if (string.IsNullOrWhiteSpace(label)) throw new ArgumentException("Scout mission type label must not be empty.", nameof(label));
        if (minDurationDays < 1 || maxDurationDays < minDurationDays) throw new ArgumentOutOfRangeException(nameof(maxDurationDays));
        if (maxScouts < 1) throw new ArgumentOutOfRangeException(nameof(maxScouts));
        Id = id.Trim();
        Label = label.Trim();
        MinDurationDays = minDurationDays;
        MaxDurationDays = maxDurationDays;
        MaxScouts = maxScouts;
        this.allowedFocuses = new HashSet<ScoutMissionFocus>(allowedFocuses ?? throw new ArgumentNullException(nameof(allowedFocuses)));
        if (this.allowedFocuses.Count == 0) throw new ArgumentException("Scout mission type needs at least one focus.", nameof(allowedFocuses));
    }

    public string Id { get; }
    public string Label { get; }
    public int MinDurationDays { get; }
    public int MaxDurationDays { get; }
    public int MaxScouts { get; }
    public IReadOnlyCollection<ScoutMissionFocus> AllowedFocuses => allowedFocuses;
    public bool Allows(ScoutMissionFocus focus) => allowedFocuses.Contains(focus);
}

/// <summary>Presentation and compatibility metadata for one reusable scout focus.</summary>
public sealed class ScoutFocusDefinition
{
    private readonly HashSet<string> compatibleMissionTypeIds;

    public ScoutFocusDefinition(ScoutMissionFocus focus, string label, string description, IEnumerable<string>? compatibleMissionTypeIds = null)
    {
        if (string.IsNullOrWhiteSpace(label)) throw new ArgumentException("Scout focus label must not be empty.", nameof(label));
        if (string.IsNullOrWhiteSpace(description)) throw new ArgumentException("Scout focus description must not be empty.", nameof(description));
        Focus = focus;
        Label = label.Trim();
        Description = description.Trim();
        compatibleMissionTypeIds = compatibleMissionTypeIds ?? Enumerable.Empty<string>();
        this.compatibleMissionTypeIds = new HashSet<string>(compatibleMissionTypeIds
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .Select(id => id.Trim()), StringComparer.Ordinal);
    }

    public ScoutMissionFocus Focus { get; }
    public string Label { get; }
    public string Description { get; }
    public IReadOnlyCollection<string> CompatibleMissionTypeIds => compatibleMissionTypeIds;
    public bool Allows(string missionTypeId) => compatibleMissionTypeIds.Count == 0 || compatibleMissionTypeIds.Contains(missionTypeId);
}

public sealed class ScoutReportTemplateDefinition
{
    public ScoutReportTemplateDefinition(ScoutMissionFocus focus, ScoutMissionStatus outcome, string title, string body, string hint, string? missionTypeId = null)
    {
        Focus = focus;
        Outcome = outcome;
        Title = Require(title, nameof(title));
        Body = Require(body, nameof(body));
        Hint = Require(hint, nameof(hint));
        MissionTypeId = string.IsNullOrWhiteSpace(missionTypeId) ? null : missionTypeId.Trim();
    }

    public ScoutMissionFocus Focus { get; }
    public ScoutMissionStatus Outcome { get; }
    public string Title { get; }
    public string Body { get; }
    public string Hint { get; }
    public string? MissionTypeId { get; }

    private static string Require(string value, string name)
    {
        if (string.IsNullOrWhiteSpace(value)) throw new ArgumentException("Value must not be empty.", name);
        return value.Trim();
    }
}

public sealed class ScoutContentDefinitionSet
{
    private readonly List<ScoutOutcomeRuleDefinition> outcomeRules;
    private readonly List<ScoutReportTemplateDefinition> reportTemplates;
    private readonly Dictionary<string, ScoutMissionTypeDefinition> missionTypes;
    private readonly Dictionary<ScoutMissionFocus, ScoutFocusDefinition> focuses;

    public ScoutContentDefinitionSet(
        IEnumerable<ScoutOutcomeRuleDefinition>? outcomeRules = null,
        IEnumerable<ScoutReportTemplateDefinition>? reportTemplates = null,
        IEnumerable<ScoutMissionTypeDefinition>? missionTypes = null,
        IEnumerable<ScoutFocusDefinition>? focuses = null)
    {
        this.outcomeRules = (outcomeRules ?? Enumerable.Empty<ScoutOutcomeRuleDefinition>()).ToList();
        this.reportTemplates = (reportTemplates ?? Enumerable.Empty<ScoutReportTemplateDefinition>()).ToList();
        this.missionTypes = (missionTypes ?? Enumerable.Empty<ScoutMissionTypeDefinition>()).ToDictionary(definition => definition.Id, StringComparer.Ordinal);
        this.focuses = (focuses ?? Enumerable.Empty<ScoutFocusDefinition>()).ToDictionary(definition => definition.Focus);
    }

    public ScoutOutcomeRuleDefinition? FindOutcome(ScoutMissionState mission)
    {
        return outcomeRules.FirstOrDefault(rule => rule.Matches(mission) && rule.Focus.HasValue)
            ?? outcomeRules.FirstOrDefault(rule => rule.Matches(mission));
    }

    public ScoutReportTemplateDefinition? FindReport(ScoutMissionState mission, ScoutMissionStatus outcome)
    {
        return reportTemplates.FirstOrDefault(template => template.Focus == mission.Focus && template.Outcome == outcome && template.MissionTypeId == mission.MissionTypeId)
            ?? reportTemplates.FirstOrDefault(template => template.Focus == mission.Focus && template.Outcome == outcome && template.MissionTypeId == null);
    }

    public ScoutMissionTypeDefinition? FindMissionType(string? id)
    {
        return !string.IsNullOrWhiteSpace(id) && missionTypes.TryGetValue(id, out var definition) ? definition : null;
    }

    public ScoutFocusDefinition? FindFocus(ScoutMissionFocus focus)
    {
        return focuses.TryGetValue(focus, out var definition) ? definition : null;
    }

    public bool HasMissionTypeDefinitions => missionTypes.Count > 0;
    public IReadOnlyCollection<ScoutMissionTypeDefinition> MissionTypes => missionTypes.Values;
    public IReadOnlyCollection<ScoutFocusDefinition> Focuses => focuses.Values;
}

public sealed class CrossSystemDataBundle
{
    public CrossSystemDataBundle(
        EvidenceDefinitionSet evidence,
        IEnumerable<FactionSignatureDefinition>? factionSignatures = null,
        IEnumerable<FactionProfileDefinition>? factionProfiles = null,
        ScoutContentDefinitionSet? scoutContent = null,
        IEnumerable<WorldTriggerDefinition>? triggers = null,
        IEnumerable<ConsequenceDefinition>? consequences = null,
        IEnumerable<FactionReactionRuleDefinition>? factionReactionRules = null,
        IEnumerable<FactionTerritoryEntryRuleDefinition>? factionTerritoryEntryRules = null)
    {
        Evidence = evidence ?? throw new ArgumentNullException(nameof(evidence));
        FactionSignatures = new FactionSignatureDefinitionSet(factionSignatures ?? Enumerable.Empty<FactionSignatureDefinition>());
        FactionProfiles = new FactionProfileDefinitionSet(factionProfiles ?? Enumerable.Empty<FactionProfileDefinition>());
        ScoutContent = scoutContent ?? new ScoutContentDefinitionSet();
        Triggers = (triggers ?? Enumerable.Empty<WorldTriggerDefinition>()).ToDictionary(trigger => trigger.Id, StringComparer.Ordinal);
        Consequences = (consequences ?? Enumerable.Empty<ConsequenceDefinition>()).ToDictionary(consequence => consequence.Id, StringComparer.Ordinal);
        FactionReactionRules = (factionReactionRules ?? Enumerable.Empty<FactionReactionRuleDefinition>()).ToList();
        FactionTerritoryEntryRules = (factionTerritoryEntryRules ?? Enumerable.Empty<FactionTerritoryEntryRuleDefinition>()).ToList();
    }

    public EvidenceDefinitionSet Evidence { get; }
    public FactionSignatureDefinitionSet FactionSignatures { get; }
    public FactionProfileDefinitionSet FactionProfiles { get; }
    public ScoutContentDefinitionSet ScoutContent { get; }
    public IReadOnlyDictionary<string, WorldTriggerDefinition> Triggers { get; }
    public IReadOnlyDictionary<string, ConsequenceDefinition> Consequences { get; }
    public IReadOnlyList<FactionReactionRuleDefinition> FactionReactionRules { get; }
    public IReadOnlyList<FactionTerritoryEntryRuleDefinition> FactionTerritoryEntryRules { get; }
    public WorldTriggerDefinition? FindTrigger(string id) => Triggers.TryGetValue(id, out var trigger) ? trigger : null;
    public ConsequenceDefinition? FindConsequence(string id) => Consequences.TryGetValue(id, out var consequence) ? consequence : null;
}

/// <summary>
/// Loads the cross-system content that is shared by world generation, scouting and later reaction
/// resolution. Runtime world state stores only stable definition IDs, never authored player text.
/// </summary>
public static class CrossSystemDataLoader
{
    private const int MinimumSupportedSchemaVersion = 1;
    private const int MaximumSupportedSchemaVersion = 2;
    private static readonly HashSet<string> SupportedDocumentTypes = new(StringComparer.Ordinal)
    {
        "evidence-definitions",
        "world-trigger-definitions",
        "consequence-definitions",
        "faction-signatures",
        "faction-profiles",
        "faction-reaction-rules",
        "faction-territory-entry-rules",
        "scout-mission-types",
        "scout-focuses",
        "scout-outcome-rules",
        "scout-report-templates"
    };

    public static CrossSystemDataBundle? LoadFromDirectory(string rootFolder)
    {
        if (string.IsNullOrWhiteSpace(rootFolder) || !Directory.Exists(rootFolder)) return null;

        return LoadFromDirectories(new[] { rootFolder });
    }

    public static CrossSystemDataBundle? LoadFromDirectories(IEnumerable<string> rootFolders)
    {
        if (rootFolders == null) throw new ArgumentNullException(nameof(rootFolders));
        var documents = rootFolders
            .Where(root => !string.IsNullOrWhiteSpace(root) && Directory.Exists(root))
            .SelectMany(root => Directory.EnumerateFiles(root, "*.json", SearchOption.AllDirectories))
            .OrderBy(path => path, StringComparer.Ordinal)
            .Where(IsSupportedDocumentFile)
            .Select(File.ReadAllText)
            .ToList();
        return documents.Count == 0 ? null : LoadFromJson(documents);
    }

    // Direct directory loading remains available for tests and older callers. It must not consume
    // schema-v2 authoring documents that are owned by CrossSystemAuthoringDataLoader.
    private static bool IsSupportedDocumentFile(string path)
    {
        try
        {
            var document = JObject.Parse(File.ReadAllText(path));
            return SupportedDocumentTypes.Contains((string?)document["documentType"] ?? string.Empty);
        }
        catch (JsonException ex)
        {
            throw new LocationDataException($"Malformed cross-system JSON document '{path}': {ex.Message}");
        }
    }

    public static CrossSystemDataBundle LoadFromJson(IEnumerable<string> jsonDocuments)
    {
        if (jsonDocuments == null) throw new ArgumentNullException(nameof(jsonDocuments));
        var evidence = new List<EvidenceDefinitionDto>();
        var triggers = new List<WorldTriggerDefinitionDto>();
        var consequences = new List<ConsequenceDefinitionDto>();
        var factionSignatures = new List<FactionSignatureDefinitionDto>();
        var factionProfiles = new List<FactionProfileDefinitionDto>();
        var factionReactionRules = new List<FactionReactionRuleDto>();
        var factionTerritoryEntryRules = new List<FactionTerritoryEntryRuleDto>();
        var scoutMissionTypes = new List<ScoutMissionTypeDto>();
        var scoutFocuses = new List<ScoutFocusDto>();
        var scoutOutcomeRules = new List<ScoutOutcomeRuleDto>();
        var scoutReportTemplates = new List<ScoutReportTemplateDto>();

        foreach (var json in jsonDocuments)
        {
            JObject envelope;
            try
            {
                envelope = JObject.Parse(json);
            }
            catch (JsonException ex)
            {
                throw new LocationDataException($"Malformed cross-system JSON document: {ex.Message}");
            }

            var schemaVersion = (int?)envelope["schemaVersion"] ?? 0;
            if (schemaVersion < MinimumSupportedSchemaVersion || schemaVersion > MaximumSupportedSchemaVersion)
            {
                throw new LocationDataException($"Unsupported schemaVersion '{schemaVersion}' (supported: {MinimumSupportedSchemaVersion}-{MaximumSupportedSchemaVersion}).");
            }

            var items = envelope["items"] as JArray ?? new JArray();
            switch ((string?)envelope["documentType"])
            {
                case "evidence-definitions": evidence.AddRange(items.ToObject<List<EvidenceDefinitionDto>>()!); break;
                case "world-trigger-definitions": triggers.AddRange(items.ToObject<List<WorldTriggerDefinitionDto>>()!); break;
                case "consequence-definitions": consequences.AddRange(items.ToObject<List<ConsequenceDefinitionDto>>()!); break;
                case "faction-signatures": factionSignatures.AddRange(items.ToObject<List<FactionSignatureDefinitionDto>>()!); break;
                case "faction-profiles": factionProfiles.AddRange(items.ToObject<List<FactionProfileDefinitionDto>>()!); break;
                case "faction-reaction-rules": factionReactionRules.AddRange(items.ToObject<List<FactionReactionRuleDto>>()!); break;
                case "faction-territory-entry-rules": factionTerritoryEntryRules.AddRange(items.ToObject<List<FactionTerritoryEntryRuleDto>>()!); break;
                case "scout-mission-types": scoutMissionTypes.AddRange(items.ToObject<List<ScoutMissionTypeDto>>()!); break;
                case "scout-focuses": scoutFocuses.AddRange(items.ToObject<List<ScoutFocusDto>>()!); break;
                case "scout-outcome-rules": scoutOutcomeRules.AddRange(items.ToObject<List<ScoutOutcomeRuleDto>>()!); break;
                case "scout-report-templates": scoutReportTemplates.AddRange(items.ToObject<List<ScoutReportTemplateDto>>()!); break;
                case "world-generation-presets": break;
                case "world-generation-option-presets": break;
                default: throw new LocationDataException($"Unsupported cross-system documentType '{(string?)envelope["documentType"]}'.");
            }
        }

        var definitions = evidence.Select(item => new EvidenceDefinition(Require(item.Id, "evidence.id"), Require(item.ScoutReportText, "evidence.scoutReportText"), item.WorldEventText, item.SymbolId)).ToList();
        if (definitions.GroupBy(item => item.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Cross-system evidence IDs must be unique.");
        }

        var builtSignatures = factionSignatures
            .Select(item => new FactionSignatureDefinition(Require(item.Id, "factionSignature.id"), Require(item.ProfileId, "factionSignature.profileId"), Require(item.Label, "factionSignature.label")))
            .ToList();
        if (builtSignatures.GroupBy(item => item.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Faction signature IDs must be unique.");
        }
        if (definitions.Any(definition => definition.SymbolId != null && !builtSignatures.Any(signature => signature.Id == definition.SymbolId)))
        {
            throw new LocationDataException("Evidence references an unknown faction signature.");
        }

        var builtFactionProfiles = factionProfiles
            .Select(item => new FactionProfileDefinition(
                Require(item.Id, "factionProfile.id"),
                Require(item.Label, "factionProfile.label"),
                item.Values,
                item.TabooActionTags,
                BuildTerritorialPolicy(item.TerritorialPolicy),
                item.ContactStyle,
                item.LeadershipStyle,
                item.ObservationRange,
                item.ObservationChannels))
            .ToList();
        if (builtFactionProfiles.GroupBy(item => item.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Faction profile IDs must be unique.");
        }

        var builtConsequences = consequences.Select(item => new ConsequenceDefinition(
            Require(item.Id, "consequence.id"),
            BuildConsequenceBranches(item))).ToList();
        if (builtConsequences.GroupBy(item => item.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Cross-system consequence IDs must be unique.");
        }
        if (builtConsequences.SelectMany(consequence => consequence.Branches).SelectMany(branch => branch.Stages)
            .Any(stage => stage.EvidenceId != null && !definitions.Any(evidenceDefinition => evidenceDefinition.Id == stage.EvidenceId)))
        {
            throw new LocationDataException("A consequence stage references an unknown evidence definition.");
        }
        if (builtConsequences.SelectMany(consequence => consequence.Branches).SelectMany(branch => branch.Stages).SelectMany(stage => stage.Effects)
            .Any(effect => effect.Kind == WorldStageEffectKind.AddEvidence && (effect.ReferenceId == null || !definitions.Any(evidenceDefinition => evidenceDefinition.Id == effect.ReferenceId))))
        {
            throw new LocationDataException("A world-stage evidence effect references an unknown evidence definition.");
        }
        if (builtConsequences.SelectMany(consequence => consequence.Branches).SelectMany(branch => branch.Stages).SelectMany(stage => stage.Effects)
            .Any(effect => effect.Kind == WorldStageEffectKind.ChangeLocationState && (effect.StateChannel == null || effect.StateId == null)))
        {
            throw new LocationDataException("A location-state world-stage effect requires stateChannel and stateId.");
        }
        if (builtConsequences.SelectMany(consequence => consequence.Branches).SelectMany(branch => branch.Stages).SelectMany(stage => stage.Effects)
            .Any(effect => effect.Kind == WorldStageEffectKind.SetTilePassability && !effect.IsBlocked.HasValue))
        {
            throw new LocationDataException("A tile-passability world-stage effect requires isBlocked.");
        }

        var builtTriggers = triggers.Select(item => new WorldTriggerDefinition(Require(item.Id, "trigger.id"), item.ConsequenceId)).ToList();
        if (builtTriggers.GroupBy(item => item.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Cross-system trigger IDs must be unique.");
        }
        if (builtTriggers.Any(trigger => trigger.ConsequenceId != null && !builtConsequences.Any(consequence => consequence.Id == trigger.ConsequenceId)))
        {
            throw new LocationDataException("A world trigger references an unknown consequence definition.");
        }

        var builtReactionRules = factionReactionRules.Select(BuildFactionReactionRule).ToList();
        if (builtReactionRules.GroupBy(rule => rule.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Faction reaction rule IDs must be unique.");
        }
        if (builtReactionRules.Any(rule => !builtTriggers.Any(trigger => trigger.Id == rule.TriggerId)))
        {
            throw new LocationDataException("A faction reaction rule references an unknown world trigger.");
        }
        if (builtReactionRules.Any(rule => rule.FactionProfileId != null && !builtFactionProfiles.Any(profile => profile.Id == rule.FactionProfileId)))
        {
            throw new LocationDataException("A faction reaction rule references an unknown faction profile.");
        }
        if (builtReactionRules.Any(rule => rule.RequiredFactionValues.Any(value => !builtFactionProfiles.Any(profile => profile.Values.Contains(value, StringComparer.Ordinal)))))
        {
            throw new LocationDataException("A faction reaction rule references an unknown faction value.");
        }
        if (builtReactionRules.Any(rule => rule.RequiredFactionTabooTags.Any(tag => !builtFactionProfiles.Any(profile => profile.TabooActionTags.Contains(tag, StringComparer.Ordinal)))))
        {
            throw new LocationDataException("A faction reaction rule references an unknown faction taboo action tag.");
        }

        var builtTerritoryEntryRules = factionTerritoryEntryRules.Select(BuildFactionTerritoryEntryRule).ToList();
        if (builtTerritoryEntryRules.GroupBy(rule => rule.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Faction territory entry rule IDs must be unique.");
        }
        if (builtTerritoryEntryRules.Any(rule => rule.FactionProfileId != null && !builtFactionProfiles.Any(profile => profile.Id == rule.FactionProfileId)))
        {
            throw new LocationDataException("A faction territory entry rule references an unknown faction profile.");
        }
        if (builtTerritoryEntryRules.Any(rule => rule.RequiredFactionValues.Any(value => !builtFactionProfiles.Any(profile => profile.Values.Contains(value, StringComparer.Ordinal)))))
        {
            throw new LocationDataException("A faction territory entry rule references an unknown faction value.");
        }

        var builtScoutMissionTypes = scoutMissionTypes.Select(item => new ScoutMissionTypeDefinition(
            Require(item.Id, "scoutMissionType.id"),
            Require(item.Label, "scoutMissionType.label"),
            item.MinDurationDays,
            item.MaxDurationDays,
            item.MaxScouts,
            (item.AllowedFocuses ?? new List<string>())
                .Select(focus => ParseEnum<ScoutMissionFocus>(focus, "scoutMissionType.allowedFocuses")))).ToList();
        if (builtScoutMissionTypes.GroupBy(item => item.Id, StringComparer.Ordinal).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Scout mission type IDs must be unique.");
        }

        var builtScoutFocuses = scoutFocuses.Select(item => new ScoutFocusDefinition(
            ParseEnum<ScoutMissionFocus>(Require(item.Id, "scoutFocus.id"), "scoutFocus.id"),
            Require(item.Label, "scoutFocus.label"),
            Require(item.Description, "scoutFocus.description"),
            item.CompatibleMissionTypeIds)).ToList();
        if (builtScoutFocuses.GroupBy(item => item.Focus).Any(group => group.Count() > 1))
        {
            throw new LocationDataException("Scout focus IDs must be unique.");
        }
        if (builtScoutMissionTypes.Count > 0 && builtScoutFocuses.Count == 0)
        {
            throw new LocationDataException("Scout mission types require scout focus definitions.");
        }
        if (builtScoutMissionTypes.Any(mission => mission.AllowedFocuses.Any(focus => !builtScoutFocuses.Any(definition => definition.Focus == focus))))
        {
            throw new LocationDataException("Scout mission type references an unknown scout focus.");
        }
        if (builtScoutFocuses.Any(focus => focus.CompatibleMissionTypeIds.Any(id => !builtScoutMissionTypes.Any(mission => mission.Id == id))))
        {
            throw new LocationDataException("Scout focus references an unknown scout mission type.");
        }
        if (builtScoutMissionTypes.Any(mission => mission.AllowedFocuses.Any(focus => !builtScoutFocuses.First(definition => definition.Focus == focus).Allows(mission.Id))))
        {
            throw new LocationDataException("Scout mission type and scout focus compatibility disagree.");
        }

        var builtScoutOutcomes = scoutOutcomeRules.Select(item => new ScoutOutcomeRuleDefinition(
            ParseEnum<ScoutMissionBehavior>(Require(item.Behavior, "scoutOutcome.behavior"), "scoutOutcome.behavior"),
            ParseEnum<ScoutMissionStatus>(Require(item.WhenStatus, "scoutOutcome.whenStatus"), "scoutOutcome.whenStatus"),
            ParseEnum<ScoutMissionStatus>(Require(item.Outcome, "scoutOutcome.outcome"), "scoutOutcome.outcome"),
            string.IsNullOrWhiteSpace(item.Focus) ? null : ParseEnum<ScoutMissionFocus>(Require(item.Focus, "scoutOutcome.focus"), "scoutOutcome.focus"), item.MissionTypeId)).ToList();
        var builtScoutReports = scoutReportTemplates.Select(item => new ScoutReportTemplateDefinition(
            ParseEnum<ScoutMissionFocus>(Require(item.Focus, "scoutReport.focus"), "scoutReport.focus"),
            ParseEnum<ScoutMissionStatus>(Require(item.Outcome, "scoutReport.outcome"), "scoutReport.outcome"),
            Require(item.Title, "scoutReport.title"), Require(item.Body, "scoutReport.body"), Require(item.Hint, "scoutReport.hint"), item.MissionTypeId)).ToList();

        if (builtScoutMissionTypes.Count > 0 && (builtScoutOutcomes.Any(rule => rule.MissionTypeId != null && !builtScoutMissionTypes.Any(mission => mission.Id == rule.MissionTypeId))
            || builtScoutReports.Any(template => template.MissionTypeId != null && !builtScoutMissionTypes.Any(mission => mission.Id == template.MissionTypeId))))
        {
            throw new LocationDataException("Scout content references an unknown scout mission type.");
        }

        return new CrossSystemDataBundle(new EvidenceDefinitionSet(definitions), builtSignatures, builtFactionProfiles, new ScoutContentDefinitionSet(builtScoutOutcomes, builtScoutReports, builtScoutMissionTypes, builtScoutFocuses), builtTriggers, builtConsequences, builtReactionRules, builtTerritoryEntryRules);
    }

    private static IReadOnlyList<ConsequenceBranchDefinition> BuildConsequenceBranches(ConsequenceDefinitionDto dto)
    {
        if (dto.Branches != null && dto.Branches.Count > 0)
        {
            if (dto.Stages != null && dto.Stages.Count > 0)
            {
                throw new LocationDataException("A consequence definition must use either legacy stages or explicit branches, not both.");
            }

            return dto.Branches.Select(branch => new ConsequenceBranchDefinition(
                Require(branch.Id, "consequence.branch.id"),
                branch.Weight,
                BuildConsequenceStages(branch.Stages))).ToList();
        }

        return new[]
        {
            new ConsequenceBranchDefinition("default", 1, BuildConsequenceStages(dto.Stages))
        };
    }

    private static IReadOnlyList<ConsequenceStageDefinition> BuildConsequenceStages(IEnumerable<ConsequenceStageDto>? stages)
    {
        return (stages ?? Enumerable.Empty<ConsequenceStageDto>())
            .Select(stage =>
            {
                var stageId = Require(stage.Id, "consequence.stage.id");
                var effects = (stage.Effects ?? new List<WorldStageEffectDto>())
                    .Select((effect, index) => BuildWorldStageEffect(effect, stageId, index))
                    .ToList();

                // Schema-v1 fields remain a concise authoring form and are translated into the
                // same generic effect pipeline as schema-v2 effect objects.
                if (!string.IsNullOrWhiteSpace(stage.EvidenceId))
                    effects.Add(new WorldStageEffectDefinition($"legacy-evidence:{stageId}", WorldStageEffectKind.AddEvidence, stage.EvidenceId));
                foreach (var situationId in stage.SituationCandidateIds ?? new List<string>())
                    effects.Add(new WorldStageEffectDefinition($"legacy-situation:{stageId}:{situationId}", WorldStageEffectKind.CreateSituation, situationId));

                return new ConsequenceStageDefinition(
                    stageId,
                    stage.DelayDays,
                    stage.EvidenceId,
                    stage.Event?.Title,
                    stage.Event?.Body,
                    stage.SituationCandidateIds,
                    effects,
                    ParseEnum(stage.Severity, WorldConsequenceSeverity.Informational));
            })
            .ToList();
    }

    private static WorldStageEffectDefinition BuildWorldStageEffect(WorldStageEffectDto dto, string stageId, int index)
    {
        var id = string.IsNullOrWhiteSpace(dto.Id) ? $"effect:{stageId}:{index + 1}" : dto.Id;
        return new WorldStageEffectDefinition(
            id,
            ParseEnum<WorldStageEffectKind>(Require(dto.Kind, "consequence.stage.effect.kind"), "consequence.stage.effect.kind"),
            dto.ReferenceId,
            dto.StateChannel,
            dto.StateId,
            dto.IsBlocked,
            dto.ActionTags,
            dto.DueDays,
            dto.ConnectionKind,
            dto.SuppressIfSituationResponseTags);
    }

    private static FactionReactionRuleDefinition BuildFactionReactionRule(FactionReactionRuleDto dto)
    {
        var relationKinds = (dto.RelationKinds ?? new List<string>()).Select(value => ParseEnum<LocationFactionRelationKind>(value, "reactionRule.relationKinds"));
        return new FactionReactionRuleDefinition(
            Require(dto.Id, "reactionRule.id"),
            Require(dto.TriggerId, "reactionRule.triggerId"),
            relationKinds,
            ParseEnum(dto.MinimumAwareness, FactionAwarenessLevel.Unaware),
            dto.FactionProfileId,
            dto.MinimumAnger,
            dto.MaximumTrust,
            dto.TrustDelta,
            dto.AngerDelta,
            dto.FearDelta,
            dto.MemoryId,
            dto.Event?.Title,
            dto.Event?.Body,
            dto.Event?.RevealsFaction ?? false,
            dto.Priority,
            dto.RequiredActionTags,
            dto.RequiredFactionValues,
            dto.RequiredFactionTabooTags);
    }

    private static FactionTerritoryEntryRuleDefinition BuildFactionTerritoryEntryRule(FactionTerritoryEntryRuleDto dto)
    {
        return new FactionTerritoryEntryRuleDefinition(
            Require(dto.Id, "territoryEntryRule.id"),
            Require(dto.EntryKind, "territoryEntryRule.entryKind").ToLowerInvariant(),
            dto.FactionProfileId,
            dto.TrustDelta,
            dto.AngerDelta,
            dto.FearDelta,
            dto.PromotesContact,
            dto.Event?.RevealsFaction ?? false,
            dto.Event?.AllowsInteraction ?? false,
            dto.Event?.Title,
            dto.Event?.Body,
            dto.Priority,
            dto.RequiredFactionValues);
    }

    private static FactionTerritorialPolicyDefinition BuildTerritorialPolicy(FactionTerritorialPolicyDto? dto)
    {
        return new FactionTerritorialPolicyDefinition(
            dto?.PermittedActionTags,
            dto?.RestrictedActionTags,
            dto?.WarningActionTags,
            BuildTerritorialPolicyResponse(dto?.WarningResponse),
            BuildTerritorialPolicyResponse(dto?.RestrictedResponse));
    }

    private static FactionTerritorialPolicyResponseDefinition BuildTerritorialPolicyResponse(FactionTerritorialPolicyResponseDto? dto)
    {
        return new FactionTerritorialPolicyResponseDefinition(
            dto?.TrustDelta ?? 0,
            dto?.AngerDelta ?? 0,
            dto?.FearDelta ?? 0,
            dto?.AwarenessIncrease ?? 0,
            dto?.Event?.Title,
            dto?.Event?.Body,
            dto?.Event?.RevealsFaction ?? false);
    }

    private static string Require(string? value, string field)
    {
        if (string.IsNullOrWhiteSpace(value)) throw new LocationDataException($"Missing required field '{field}'.");
        return value.Trim();
    }

    private static TEnum ParseEnum<TEnum>(string? value, TEnum defaultValue) where TEnum : struct, Enum
    {
        if (string.IsNullOrWhiteSpace(value)) return defaultValue;
        if (Enum.TryParse<TEnum>(value, true, out var parsed)) return parsed;
        throw new LocationDataException($"Unknown enum value '{value}'.");
    }

    private static TEnum ParseEnum<TEnum>(string value, string field) where TEnum : struct, Enum
    {
        if (Enum.TryParse<TEnum>(value, true, out var parsed)) return parsed;
        throw new LocationDataException($"Unknown value '{value}' for '{field}'.");
    }

